import process from 'node:process';
import { CliExit, parseCliArgs, renderMarkdownTriplet } from './lib/index.mjs';

export function main(argv = process.argv.slice(2), scriptPath = process.argv[1]) {
  try {
    const parsedArgs = parseCliArgs(argv, scriptPath);
    const result = renderMarkdownTriplet(parsedArgs);

    if (result.stdout.length > 0) {
      process.stdout.write(result.stdout);
    }

    if (result.stderr.length > 0) {
      process.stderr.write(result.stderr);
    }

    process.exitCode = result.exitCode;
  } catch (error) {
    if (error instanceof CliExit) {
      const stream = error.streamName === 'stdout' ? process.stdout : process.stderr;
